};


/**
 * @method
 * @name scwin.print
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.print = function () {
    /* sdd-asis-lifecycle:begin fn_print — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const formAdmTnstTpCd = '' + dma_formMap.get("formAdmTnstTpCd") + '';
    document.print_iframe.setStyle("display", "");
    let bodyHtml = $("#docpathframe").contents().find("body").html();
    if (formAdmTnstTpCd !== '1') {
        bodyHtml = '<table><tr><td>' + bodyHtml + '</td></tr></table>';
    }
    if ($('#waringCheck label').hasClass('on')) {
        $("#print_iframe").contents().find("head").html($("#docpathframe").contents().find("head").html() + $("#print_iframe").contents().find("head").html());
        $("#print_iframe").contents().find("#formArea").html(bodyHtml);
        $("#print_iframe").contents().find("#waring").html($c.util.getComponent('txt_waring').getValue());
        $("#print_iframe").contents().find("#waring").attr("style", "margin-top:20px; padding:12px; font-size:13px; text-align:left; border:2px solid #e1e1e1; background:#f4f4f4;");
    } else {
        $("#print_iframe").contents().find("head").html($("#docpathframe").contents().find("head").html() + $("#print_iframe").contents().find("head").html());
        $("#print_iframe").contents().find("#formArea").html(bodyHtml);
        $("#print_iframe").contents().find("#waring").attr("style", "");
        console.error("[sdd] 미실현 동작: set_label (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_label — {target}.setLabel({args}) */
    }
    document.print_iframe.focus();
    console.error("[sdd] 미실현 동작: set_focus (대상 미해석) — 전환 미완"); /* unresolved-target intent:set_focus — {target}.focus({args}) */
    frames['print_iframe'].print();
    document.print_iframe.setStyle("display", "none");
    /* sdd-asis-lifecycle:end */
};


/**
