*/
scwin.createForm = async function (formAdmInstTpCd, formCd, formVer) {
    /* sdd-asis-lifecycle:begin fn_createForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (formAdmInstTpCd === '2') {
        var url = "/submission/disclosure.do?method=createDartFormPreview&formCd=" + formCd;
        $c.win.setPageFrameSrc(null, (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    } else {
        await alertE('해당서식은 기본정보의 기타메뉴에서 조회공시 요구 및 답변 내역의 답변버튼을 클릭하여 작성하셔야 합니다.');
        return;
        var url = "/submission/disclosure.do?method=createForm&formCd=" + formCd;
        $c.win.setPageFrameSrc(null, (function (__u) { var __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(url));
    }
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.autoResize
 * @author Inswave
 * @date 2026. 09. 29
 * @param id
 * @returns
 * @hidden N
*/
scwin.autoResize = function (id) {
    /* sdd-asis-lifecycle:begin autoResize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let he;
    let wi;
    if (document.getElementById) {
        he = $c.util.getComponent(id).contentWindow.document.body.scrollHeight;
        wi = $c.util.getComponent(id).contentWindow.document.body.scrollWidth;
    }
    wi = wi + 25;
    $c.util.getComponent(id).height = (he) + 'px';
    $c.util.getComponent(id).width = (wi) + 'px';
    scwin.sectionH();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.alertE
 * @author Inswave
 * @date 2026. 09. 29
 * @param msg callback
 * @returns
 * @hidden N
*/
scwin.alertE = async function (msg, callback) {
    // as-is 는 화면 안 #pAlertText/#divAlertMsg 를 만졌다 — 엔진 프레임 접두 때문에
    // 그 선택자는 어디서도 못 찾는다. 표준 알림으로 낸다(메시지가 사라지지 않게).
    await $c.win.alert(msg);
    if (typeof callback === 'function') { await callback(); }
};

async function alertE(msg, callback) { return await scwin.alertE(msg, callback); }

/**
